package com.brannenservices.fieldassistant

import android.app.Activity
import android.graphics.*
import android.os.Bundle
import android.view.*
import kotlin.math.*

class MainActivity:Activity(){
 override fun onCreate(b:Bundle?){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);window.setFlags(1024,1024);window.decorView.systemUiVisibility=5894;setContentView(GameView(this))}
 class GameView(a:Activity):View(a){
  data class Bird(var x:Float,var hp:Int,val max:Int,val boss:Boolean=false,var hit:Int=-1,var flash:Float=0f,var dir:Int=-1)
  data class Beer(val x:Float,var taken:Boolean=false)
  val W=640;val H=360;val G=278f;val WORLD=3000f
  val frame=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888);val c=Canvas(frame);val p=Paint().apply{isAntiAlias=false};val pix=Paint().apply{isAntiAlias=false;isFilterBitmap=false}
  var px=105f;var py=G;var vy=0f;var cam=0f;var face=1;var joy=0f;var joyId=-1;var started=false;var dead=false;var won=false;var hp=100;var score=0;var cans=0;var attack=0f;var attackId=0;var hurt=0f;var t=0f;var last=System.nanoTime();var combo=0;var comboT=0f;var wave=1;var msg="";var msgT=0f
  val birds=mutableListOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true))
  val beers=mutableListOf(Beer(650f),Beer(1330f),Beer(2050f));val obstacles=floatArrayOf(900f,1510f,2300f)
  override fun onDraw(o:Canvas){val n=System.nanoTime();val dt=((n-last)/1e9f).coerceAtMost(.04f);last=n;if(started&&!dead&&!won)update(dt);drawGame();o.drawBitmap(frame,null,Rect(0,0,width,height),pix);postInvalidateOnAnimation()}
  fun update(dt:Float){
   t+=dt;attack=max(0f,attack-dt);hurt=max(0f,hurt-dt);comboT=max(0f,comboT-dt);msgT=max(0f,msgT-dt);if(comboT<=0)combo=0
   if(abs(joy)>.12f){face=if(joy>0)1 else -1;val old=px;var next=(px+joy*220f*dt).coerceIn(30f,WORLD-40);if(py>G-42){for(o in obstacles){if(old<o-35&&next>=o-35){next=o-36;if(hurt<=0)hazard(face*-1)}else if(old>o+35&&next<=o+35){next=o+36;if(hurt<=0)hazard(face*-1)}}};px=next}
   vy+=780f*dt;py+=vy*dt;if(py>G){py=G;vy=0f};cam+=(px-235f-cam)*min(1f,dt*7);cam=cam.coerceIn(0f,WORLD-W);wave=if(px<1000)1 else if(px<2000)2 else 3
   birds.forEach{b->b.flash=max(0f,b.flash-dt);if(b.hp<=0)return@forEach;val dx=px-b.x;b.dir=if(dx>0)1 else -1;if(abs(dx)<(if(b.boss)390f else 260f))b.x+=b.dir*(if(b.boss)78f else 55f)*dt;if(attack>0&&b.hit!=attackId){val d=(b.x-px)*face;if(d in 5f..105f&&py>G-90){b.hp--;b.hit=attackId;b.flash=.1f;b.x+=face*(if(b.boss)20f else 38f);combo++;comboT=1.3f;score+=(if(b.boss)250 else 100)*(1+(combo-1)/3);say(if(combo>2)"$combo HIT COMBO!" else "BONK!");if(b.hp<=0)score+=if(b.boss)1800 else 300}};if(abs(b.x-px)<(if(b.boss)48f else 31f)&&py>G-55&&hurt<=0){hp=max(0,hp-(if(b.boss)18 else 10));hurt=.7f;px+=if(dx>0)-55 else 55;if(hp<=0)dead=true}}
   beers.forEach{if(!it.taken&&abs(it.x-px)<34&&py>G-70){it.taken=true;cans++;hp=min(100,hp+25);score+=200;say("COLD ONE ACQUIRED!")}};if(birds.last().hp<=0&&px>2780)won=true
  }
  fun hazard(push:Int){hp=max(0,hp-8);hurt=.55f;px=(px+push*16).coerceIn(30f,WORLD-40);say("WATCH THE COOLER!");if(hp<=0)dead=true}
  fun say(s:String){msg=s;msgT=1.1f};fun col(v:Int){p.color=v;p.style=Paint.Style.FILL;p.shader=null};fun r(l:Float,t:Float,rr:Float,b:Float,v:Int){col(v);c.drawRect(l,t,rr,b,p)}
  fun text(s:String,x:Float,y:Float,z:Float,v:Int,center:Boolean=false){col(v);p.typeface=Typeface.create(Typeface.MONOSPACE,Typeface.BOLD);p.textSize=z;p.textAlign=if(center)Paint.Align.CENTER else Paint.Align.LEFT;c.drawText(s,x,y,p);p.textAlign=Paint.Align.LEFT}
  fun drawGame(){sky();farCity();marina();dock();props();beers.filter{!it.taken}.forEach{beer(it)};birds.filter{it.hp>0}.forEach{bird(it)};man();foreground();hud();controls();if(!started)panel("POOL NOODLE PANIC","TAP TO START");if(dead)panel("WELL, THAT WENT BAD","TAP TO TRY AGAIN");if(won)panel("LEVEL COMPLETE","ALPHA FLAMINGO DEFEATED");if(msgT>0){r(205f,304f,435f,327f,Color.rgb(14,13,29));text(msg,320f,320f,10f,Color.YELLOW,true)}}
  fun sky(){p.shader=LinearGradient(0f,38f,0f,218f,Color.rgb(50,31,105),Color.rgb(250,91,72),Shader.TileMode.CLAMP);c.drawRect(0f,0f,640f,218f,p);p.shader=null;for(i in 0..9){val x=(i*83-(cam*.025f).toInt()%83).toFloat();r(x,77f+(i%4)*12,x+45,80f+(i%4)*12,Color.rgb(119,51,104));r(x+15,82f+(i%4)*12,x+64,85f+(i%4)*12,Color.rgb(177,57,94))};col(Color.rgb(255,194,70));c.drawCircle(478f,151f,43f,p);for(i in 0..5)r(438f+i*5,150f+i*6,519f-i*7,153f+i*6,Color.rgb(255,221,105))}
  fun farCity(){val off=-(cam*.08f%900);for(k in 0..1){val b=off+k*900;r(b+50,153f,b+83,205f,Color.rgb(50,45,76));r(b+92,167f,b+118,205f,Color.rgb(57,47,77));r(b+130,142f,b+166,205f,Color.rgb(49,43,69));for(x in 55..160 step 12)for(y in 151..196 step 11)if((x+y)%3!=0)r(b+x,y.toFloat(),b+x+4,y+5f,Color.rgb(241,151,75))};for(i in -1..6)palm(i*135f-(cam*.12f%135f)+35)}
  fun palm(x:Float){r(x-2,124f,x+3,218f,Color.rgb(32,30,43));for(i in -3..3){val q=Path();q.moveTo(x,126f);q.lineTo(x+i*22,108f+abs(i)*5);q.lineTo(x+i*11,132f);q.close();col(if(i%2==0)Color.rgb(19,67,58) else Color.rgb(28,83,64));c.drawPath(q,p)}}
  fun marina(){r(0f,190f,640f,224f,Color.rgb(18,82,122));for(i in 0..10){val x=i*70f-(cam*.18f%70);r(x,204f+(i%3)*5,x+39,206f+(i%3)*5,Color.rgb(52,142,159));r(x+18,216f-(i%2)*5,x+58,218f-(i%2)*5,Color.rgb(241,128,84))};sailboat(520f-(cam*.16f%900),181f);tiki(120f-cam*.34f)}
  fun sailboat(x:Float,y:Float){if(x !in -100f..740f)return;r(x,y,x+45,y+5,Color.rgb(42,38,55));r(x+20,y-41,x+22,y,Color.rgb(54,42,50));val q=Path();q.moveTo(x+22,y-39);q.lineTo(x+22,y-4);q.lineTo(x+42,y-5);q.close();col(Color.rgb(238,214,174));c.drawPath(q,p);r(x+4,y+5,x+41,y+9,Color.rgb(24,36,52))}
  fun tiki(x:Float){if(x !in -180f..720f)return;r(x,154f,x+126,224f,Color.rgb(79,48,35));r(x+7,168f,x+119,218f,Color.rgb(108,64,39));for(i in 0..5)r(x+12+i*18,181f,x+17+i*18,215f,Color.rgb(49,32,29));val q=Path();q.moveTo(x-12,160f);q.lineTo(x+65,127f);q.lineTo(x+139,160f);q.close();col(Color.rgb(72,48,32));c.drawPath(q,p);r(x+18,166f,x+108,182f,Color.rgb(205,149,80));text("SALTY FLAMINGO",x+63,177f,7f,Color.rgb(45,29,26),true)}
  fun dock(){r(0f,224f,640f,279f,Color.rgb(73,49,38));for(i in 0..12){val x=i*55f-(cam*.68f%55);r(x,224f,x+50,274f,if(i%2==0)Color.rgb(145,91,52) else Color.rgb(121,72,46));r(x,228f,x+50,232f,Color.rgb(194,127,67));r(x+3,267f,x+49,272f,Color.rgb(72,45,37))};r(0f,279f,640f,360f,Color.rgb(7,55,82));for(i in 0..11){val x=i*63f-(cam*.38f%63);r(x,292f+(i%3)*13,x+39,295f+(i%3)*13,Color.rgb(26,112,140));r(x+15,331f-(i%2)*13,x+58,334f-(i%2)*13,Color.rgb(18,90,124));r(x+29,346f-(i%4)*7,x+52,349f-(i%4)*7,Color.rgb(198,102,72))}}
  fun props(){sign(360f,"GOOD BEER","BAD IDEAS");sign(1660f,"NO WAKE","JUST CHAOS");sign(2750f,"BEWARE","GATORS");obstacles.forEach{wx->val x=wx-cam;if(x in -50f..690f)c.drawBitmap(SpriteArt.cooler,null,RectF(x-28,G-28,x+28,G+13),pix)};val ex=2860f-cam;if(ex in -80f..720f){c.drawBitmap(SpriteArt.exit,null,RectF(ex-40,G-100,ex+40,G),pix);text("EXIT",ex,G-104,10f,Color.YELLOW,true)}}
  fun foreground(){for(wx in floatArrayOf(540f,1320f,2140f)){val x=wx-cam;if(x in -40f..680f){r(x-7,264f,x+8,345f,Color.rgb(47,35,31));r(x-11,260f,x+12,270f,Color.rgb(92,60,39));r(x-9,263f,x+10,267f,Color.rgb(160,102,53))}}}
  fun sign(wx:Float,a:String,b:String){val x=wx-cam;if(x !in -100f..740f)return;r(x-4,177f,x+4,225f,Color.rgb(62,38,27));r(x-51,155f,x+51,181f,Color.rgb(163,104,52));r(x-48,158f,x+48,178f,Color.rgb(205,145,73));text(a,x,168f,8f,Color.rgb(37,27,26),true);text(b,x,176f,8f,Color.rgb(37,27,26),true)}
  fun man(){if(hurt>0&&(hurt*12).toInt()%2==0)return;val x=px-cam;val moving=abs(joy)>.12f&&py>=G-1;val cycle=t*10f;val bob=if(moving)abs(sin(cycle))*3.2f else sin(t*2.4f)*.6f;val sway=if(moving)sin(cycle)*2.3f else 0f;val dst=RectF(x-38+sway,py-112+bob,x+38+sway,py+bob);c.save();c.scale(face.toFloat(),1f,x,py);if(moving)c.rotate(sin(cycle)*1.7f,x,py-50);c.drawBitmap(SpriteArt.man,null,dst,pix);c.restore();if(moving){val step=sin(cycle);col(Color.rgb(226,145,91));p.strokeWidth=5f;c.drawLine(x-12,py-2,x-12-step*8,py+5,p);c.drawLine(x+11,py-2,x+11+step*8,py+5,p)};val handX=x+face*31f+sway;val handY=py-43f+bob;val phase=(1f-attack/.2f).coerceIn(0f,1f);val deg=if(attack>0){if(face>0)-38f+phase*92f else 218f-phase*92f}else if(face>0)-18f else 198f;val z=Math.toRadians(deg.toDouble());val ux=cos(z).toFloat();val uy=sin(z).toFloat();val sx=handX-face*3;val sy=handY+2;val ex=handX+ux*78;val ey=handY+uy*78;col(Color.rgb(11,92,166));p.strokeWidth=13f;p.strokeCap=Paint.Cap.ROUND;c.drawLine(sx,sy,ex,ey,p);col(Color.rgb(54,188,255));p.strokeWidth=9f;c.drawLine(sx,sy-1,ex,ey-1,p);col(Color.rgb(142,225,255));p.strokeWidth=2f;c.drawLine(sx+ux*8,sy-3,ex-ux*8,ey-3,p);col(Color.rgb(226,145,91));c.drawCircle(handX,handY,5.5f,p);p.strokeCap=Paint.Cap.BUTT}
  fun bird(b:Bird){val x=b.x-cam;if(x !in -120f..760f)return;val s=if(b.boss)1.48f else 1f;val w=82*s;val h=104*s;val moving=abs(px-b.x)<(if(b.boss)390 else 260);val cycle=t*(if(b.boss)7f else 8.5f)+b.x*.02f;val bob=if(moving)abs(sin(cycle))*3f else sin(cycle*.4f);val stride=if(moving)sin(cycle)*5f*s else 0f;val dst=RectF(x-w/2,G-h+bob,x+w/2,G+bob);c.save();c.scale(b.dir.toFloat(),1f,x,G);if(moving)c.rotate(sin(cycle)*1.4f,x,G-48*s);if(b.flash>0){p.colorFilter=PorterDuffColorFilter(Color.WHITE,PorterDuff.Mode.SRC_ATOP);c.drawBitmap(SpriteArt.flamingo,null,dst,p);p.colorFilter=null}else c.drawBitmap(SpriteArt.flamingo,null,dst,pix);c.restore();if(moving){col(Color.rgb(205,68,113));p.strokeWidth=3f;c.drawLine(x-10*s,G-15*s,x-10*s+stride,G,p);c.drawLine(x+8*s,G-15*s,x+8*s-stride,G,p);col(Color.rgb(28,24,29));p.strokeWidth=3f;c.drawLine(x-13*s+stride,G,x-5*s+stride,G,p);c.drawLine(x+5*s-stride,G,x+13*s-stride,G,p)};if(b.boss){text("ALPHA",x,G-h-7,8f,Color.YELLOW,true);r(x-35,G-h-3,x+35,G-h+2,Color.rgb(55,25,30));r(x-35,G-h-3,x-35+70f*b.hp/b.max,G-h+2,Color.RED)}}
  fun beer(q:Beer){val x=q.x-cam;if(x !in -30f..670f)return;val y=G-38+sin(t*5+q.x)*3;c.drawBitmap(SpriteArt.beer,null,RectF(x-13,y-24,x+13,y+20),pix)}
  fun hud(){r(0f,0f,640f,38f,Color.rgb(12,11,29));text("HOLD MY BEER",12f,14f,10f,Color.YELLOW);r(12f,21f,184f,31f,Color.rgb(55,45,54));r(15f,24f,15f+166f*hp/100f,28f,if(hp>30)Color.rgb(42,215,70) else Color.RED);text("FLORIDA MAN",320f,17f,18f,Color.YELLOW,true);text("POOL NOODLE PANIC  •  WAVE $wave/3",320f,30f,7f,Color.WHITE,true);text("SCORE $score",520f,14f,8f,Color.WHITE);text("COLD ONES x $cans",520f,28f,8f,Color.WHITE);if(combo>1)text("COMBO x$combo",455f,48f,9f,Color.YELLOW)}
  fun controls(){col(Color.argb(175,10,20,35));c.drawCircle(48f,321f,31f,p);col(Color.rgb(25,80,158));c.drawCircle(555f,321f,25f,p);col(Color.rgb(190,30,38));c.drawCircle(610f,321f,25f,p);text("JUMP",555f,325f,8f,Color.WHITE,true);text("WHACK",610f,325f,8f,Color.WHITE,true)}
  fun panel(a:String,b:String){r(102f,126f,538f,220f,Color.argb(235,11,11,26));r(107f,131f,533f,215f,Color.rgb(36,27,60));text(a,320f,165f,20f,Color.YELLOW,true);text(b,320f,193f,10f,Color.WHITE,true)}
  fun reset(){px=105f;py=G;vy=0f;cam=0f;hp=100;score=0;cans=0;dead=false;won=false;combo=0;birds.clear();birds.addAll(listOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true)));beers.clear();beers.addAll(listOf(Beer(650f),Beer(1330f),Beer(2050f)))}
  override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){MotionEvent.ACTION_DOWN,MotionEvent.ACTION_POINTER_DOWN->{val i=e.actionIndex;val id=e.getPointerId(i);val x=e.getX(i)/width*W;val y=e.getY(i)/height*H;if(!started||dead||won){if(dead||won)reset();started=true;return true};if(x<130&&y>270){joyId=id;joy=((x-48)/48).coerceIn(-1f,1f)}else if(x>585&&y>285){attack=.2f;attackId++}else if(x>525&&y>285&&py>=G-1){vy=-330f}};MotionEvent.ACTION_MOVE->{if(joyId>=0)for(i in 0 until e.pointerCount)if(e.getPointerId(i)==joyId){val x=e.getX(i)/width*W;joy=((x-48)/48).coerceIn(-1f,1f)}};MotionEvent.ACTION_UP,MotionEvent.ACTION_POINTER_UP,MotionEvent.ACTION_CANCEL->{if(e.getPointerId(e.actionIndex)==joyId){joyId=-1;joy=0f}}};return true}
 }
}